// Validate HUMAN-entered demo response. Explicit labels; never a vendor response.
// Currency match against the referenced offer is checked at persist time via snapshot.
const b = $input.first().json;
const bad = [];
if (!b.procurement_id) bad.push('procurement_id required');
if (!b.offer_id) bad.push('offer_id required');
if (!(typeof b.revised_price === 'number' && b.revised_price > 0)) bad.push('revised_price must be an entered number > 0 (no prepopulation)');
if (!b.currency || !/^[A-Za-z]{3}$/.test(String(b.currency))) bad.push('currency required (ISO code)');
if (bad.length) throw new Error('demo response rejected: ' + bad.join('; '));
return [{ json: { operation: 'insert_demo_responses', payload: { procurement_id: b.procurement_id, responses: [{ offer_id: b.offer_id, revised_price: b.revised_price, currency: String(b.currency).toUpperCase(), delivery_days: b.delivery_days ?? 'unavailable', warranty: b.warranty ?? 'unavailable', payment_terms: b.payment_terms ?? 'unavailable', notes: b.notes ?? '' }] } } }];
